const countable = (e) => e.approval !== "pending" && e.approval !== "rejected";
const expIn = (f, t) =>
  S.expenses.filter((e) => countable(e) && inRange(e.date, f, t));
const incIn = (f, t) => S.income.filter((i) => inRange(i.date, f, t));
const incRecv = (a) => sum(a.filter((i) => i.status !== "due"));
const meEmp = () => {
  try {
    return localStorage.getItem("moas-me-emp") || "";
  } catch {
    return "";
  }
};
const canEditRow = (e) =>
  ME.manager ||
  (e.createdBy && e.createdBy === ME.uid && e.approval !== "approved");

function balances() {
  const b = {};
  S.cfg.accounts.forEach((a) => (b[a.id] = Number(a.opening) || 0));
  S.income.forEach((i) => {
    if (i.status !== "due" && b[i.account] != null)
      b[i.account] += Number(i.amount) || 0;
  });
  S.expenses.forEach((e) => {
    if (countable(e) && e.status === "paid" && b[e.account] != null)
      b[e.account] -= Number(e.amount) || 0;
  });
  S.transfers.forEach((t) => {
    const a = Number(t.amount) || 0;
    if (b[t.from] != null) b[t.from] -= a;
    if (b[t.to] != null) b[t.to] += a;
  });
  S.floats.forEach((f) => {
    const a = Number(f.amount) || 0;
    if (b[f.account] == null) return;
    if (f.type === "give" || f.type === "reimburse") b[f.account] -= a;
    else if (f.type === "return") b[f.account] += a;
  });
  return b;
}
function rangeOf(p, ref) {
  ref = ref || today();
  if (p === "today") return { from: ref, to: ref, label: "আজ" };
  if (p === "yesterday") {
    const y = addDays(ref, -1);
    return { from: y, to: y, label: "গতকাল" };
  }
  if (p === "week") {
    const f = weekStart(ref);
    return { from: f, to: addDays(f, 6), label: "এই সপ্তাহ" };
  }
  if (p === "lastweek") {
    const f = addDays(weekStart(ref), -7);
    return { from: f, to: addDays(f, 6), label: "গত সপ্তাহ" };
  }
  if (p === "month") return { ...monthRange(ref.slice(0, 7)), label: "এই মাস" };
  if (p === "lastmonth")
    return { ...monthRange(addMonths(ref.slice(0, 7), -1)), label: "গত মাস" };
  if (p === "year")
    return {
      from: ref.slice(0, 4) + "-01-01",
      to: ref.slice(0, 4) + "-12-31",
      label: "এই বছর",
    };
  return { from: "", to: "", label: "সব সময়" };
}

