const capCache = {};
function cap(name) {
  if (!(name in capCache))
    capCache[name] =
      window.claude && typeof window.claude.use === "function"
        ? window.claude.use(name).catch(() => null)
        : Promise.resolve(null);
  return capCache[name];
}


// MOAS MONGODB FRONTEND V1
const Store = {
  db: null,
  writing: {},

  async request(url, options = {}) {
    const response = await fetch(url, {
      ...options,
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/json",
        ...(options.headers || {})
      }
    });

    if (!response.ok) {
      const error = new Error(
        "Server request failed: " + response.status
      );
      error.code = String(response.status);
      throw error;
    }

    return response.json();
  },

  async init() {
    const session = await fetch("/api/auth/me", {
      credentials: "same-origin"
    });

    if (!session.ok) {
      AUTHED = false;
      ME.mode = "local";
      ME.canWrite = false;
      loaded();
      setSync();
      render();
      return;
    }

    AUTHED = true;

    const data = await this.request("/api/state");

    for (const col of COLS) {
      if (!Array.isArray(data[col])) {
        throw new Error("Missing database module: " + col);
      }
    }

    COLS.forEach(col => {
      S[col] = data[col];
    });

    S.cfg = mergeCfg(data.cfg || {});

    ME.mode = "db";
    ME.manager = true;
    ME.owner = true;
    ME.canWrite = true;
    ME.uid = "admin";

    loaded();
    setSync();
    schedule();
    render();

    console.log("[MOAS] MongoDB data loaded");
  },

  async write(path, fn) {
    while (this.writing[path]) {
      try {
        await this.writing[path];
      } catch {}
    }

    const pending = Promise.resolve().then(fn);
    this.writing[path] = pending;

    try {
      return await pending;
    } catch (error) {
      writeErr(error);
      throw error;
    } finally {
      if (this.writing[path] === pending) {
        delete this.writing[path];
      }
    }
  },

  async save(col, obj, { silent } = {}) {
    if (!AUTHED || ME.mode !== "db") {
      throw new Error("Database session not ready");
    }

    if (!COLS.includes(col)) {
      throw new Error("Invalid module: " + col);
    }

    obj = clone(obj);

    if (!obj.id) obj.id = newId();

    if (col === "expenses" && !obj.vno) {
      obj.vno = nextVno();
    }

    obj.updatedAt = Date.now();

    if (!obj.createdAt) {
      obj.createdAt = Date.now();
    }

    if (!obj.createdBy) {
      obj.createdBy = ME.uid;
    }

    await this.write(col + "/" + obj.id, () =>
      this.request(
        "/api/state/" +
        encodeURIComponent(col) + "/" +
        encodeURIComponent(obj.id),
        {
          method: "PUT",
          body: JSON.stringify(obj)
        }
      )
    );

    const arr = S[col];
    const index = arr.findIndex(x => x.id === obj.id);

    if (index >= 0) arr[index] = obj;
    else arr.push(obj);

    if (!silent) schedule();

    return obj;
  },

  async del(col, id, { silent } = {}) {
    if (!AUTHED || ME.mode !== "db") {
      throw new Error("Database session not ready");
    }

    if (!COLS.includes(col)) {
      throw new Error("Invalid module");
    }

    await this.write(col + "/" + id, () =>
      this.request(
        "/api/state/" +
        encodeURIComponent(col) + "/" +
        encodeURIComponent(id),
        { method: "DELETE" }
      )
    );

    S[col] = S[col].filter(x => x.id !== id);

    if (!silent) schedule();
  },

  async saveCfg(config) {
    if (!AUTHED || ME.mode !== "db") {
      throw new Error("Database session not ready");
    }

    const merged = mergeCfg(config);

    await this.write("config/main", () =>
      this.request("/api/state/config", {
        method: "PUT",
        body: JSON.stringify(merged)
      })
    );

    S.cfg = merged;
    schedule();
  }
};

function writeErr(e) {
  const c = e?.code;
  if (c === "invalid_argument") {
    ME.canWrite = false;
    toast("সেভ হয়নি: আপনার এখানে লেখার অনুমতি নেই, অথবা ডেটা খুব বড়।", "err");
  } else if (c === "quota_exceeded")
    toast(
      "ডেটাবেস পূর্ণ — সেটিংস থেকে ব্যাকআপ নিয়ে পুরনো এন্ট্রি মুছুন।",
      "err",
    );
  else if (c === "revoked")
    toast("অ্যাক্সেস বাতিল হয়েছে — এই সেশনে আর সেভ হবে না।", "err");
  else toast("সেভ হয়নি (" + (c || "error") + ") — আবার চেষ্টা করুন।", "err");
}
async function pool(items, n, fn, onProg) {
  let i = 0,
    done = 0;
  const run = async () => {
    while (i < items.length) {
      const k = i++;
      try {
        await fn(items[k]);
      } catch {}
      done++;
      onProg && onProg(done, items.length);
    }
  };
  await Promise.all(Array.from({ length: Math.min(n, items.length) }, run));
}

/* ================= ui plumbing ================= */
let isLoaded = false,
  renderQ = false;
function loaded() {
  if (!isLoaded) {
    isLoaded = true;
    if (AUTHED && !authTokenValid()) AUTHED = false;
    render();
  }
}
function schedule() {
  if (!isLoaded || renderQ) return;
  renderQ = true;
  requestAnimationFrame(() => {
    renderQ = false;
    render();
  });
}
function banner(t) {
  const b = $("#banner");
  b.innerHTML = tr(t);
  b.classList.toggle("on", !!t);
}
function setSync() {
  $("#syncDot").classList.toggle("off", ME.mode !== "db");
  $("#syncTxt").textContent = tr(
    ME.mode === "db" ? "টিমের সাথে লাইভ সিঙ্ক" : "শুধু এই ব্রাউজারে সেভ হচ্ছে",
  );
  $("#roleTxt").textContent = tr(
    ME.manager ? "ভূমিকা: ম্যানেজার / অ্যাডমিন" : "ভূমিকা: টিম মেম্বার",
  );
}
function toast(msg, type = "", action) {
  const t = document.createElement("div");
  t.className = "toast " + type;
  t.innerHTML = tr(`<span style="flex:1">${msg}</span>`);
  if (action) {
    const b = document.createElement("button");
    b.textContent = tr(action.label);
    b.onclick = () => {
      action.fn();
      t.remove();
    };
    t.append(b);
  }
  const box = $("#toasts");
  box.append(t);
  while (box.children.length > 2) box.firstElementChild.remove();
  setTimeout(() => t.remove(), action ? 6000 : 3500);
}

