/* ================= i18n ================= */
let TRD = null;
function tr(s) {
  s = String(s ?? "");
  if (LANG !== "en") return s.indexOf(MK) >= 0 ? unmk(s) : s;
  if (!TRD) {
    const list = Object.entries(window.EN_DICT || {}).sort(
      (a, b) => b[0].length - a[0].length,
    );
    TRD = {
      list,
      rx: [
        [/(\d[\d,.]*)\s?টি/g, "$1"],
        [/(\d[\d,.]*)\s?জন/g, "$1 people"],
        [/(^|\s)এ(?=\s|$)/g, "$1"],
      ],
    };
  }
  const parts = s.split(MK);
  for (let i = 0; i < parts.length; i += 2) {
    let p = parts[i];
    if (!/[\u0980-\u09FF]/.test(p)) continue;
    for (const [b, e] of TRD.list) if (p.includes(b)) p = p.split(b).join(e);
    for (const [re, rep] of TRD.rx) p = p.replace(re, rep);
    parts[i] = p;
  }
  return parts.join("");
}

