const charts = {};
function killCharts() {
  Object.keys(charts).forEach((k) => {
    try {
      charts[k].destroy();
    } catch {}
    delete charts[k];
  });
}
function cssv(n) {
  return getComputedStyle(document.documentElement).getPropertyValue(n).trim();
}
function chart(id, cfg) {
  const el = document.getElementById(id);
  if (!el || !window.Chart) return;
  const tc = cssv("--muted"),
    gc = cssv("--line-2");
  Chart.defaults.font.family = "Manrope, 'Hind Siliguri', sans-serif";
  Chart.defaults.color = tc;
  const uo = cfg.options || {},
    up = uo.plugins || {},
    ut = up.tooltip || {};
  cfg.options = {
    responsive: true,
    maintainAspectRatio: false,
    ...uo,
    plugins: {
      ...up,
      legend: { display: false, ...(up.legend || {}) },
      tooltip: {
        backgroundColor: "#0E1A2F",
        padding: 10,
        cornerRadius: 8,
        ...ut,
        callbacks: {
          label: (c) =>
            " " + (c.dataset.label ? c.dataset.label + ": " : "") + fmt(c.raw),
          ...(ut.callbacks || {}),
        },
      },
    },
  };
  if (cfg.type !== "doughnut") {
    cfg.options.scales = cfg.options.scales || {};
    const axv = {
      grid: { color: gc, drawTicks: false },
      border: { display: false },
      ticks: { callback: (v) => fmtK(v), padding: 8 },
    };
    const axc = {
      grid: { display: false },
      border: { display: false },
      ticks: { padding: 6, maxRotation: 0, autoSkip: true },
    };
    if (cfg.options.indexAxis === "y") {
      cfg.options.scales.x = { ...axv, ...(cfg.options.scales.x || {}) };
      cfg.options.scales.y = { ...axc, ...(cfg.options.scales.y || {}) };
    } else {
      cfg.options.scales.y = { ...axv, ...(cfg.options.scales.y || {}) };
      cfg.options.scales.x = { ...axc, ...(cfg.options.scales.x || {}) };
    }
  }
  charts[id] = new Chart(el, cfg);
}
