/* ================= Accounts ================= */
function ledger(aid) {
  const L = [];
  S.income.forEach((i) => {
    if (i.account === aid && i.status !== "due")
      L.push({
        date: i.date,
        t:
          tr("টাকা জমা") +
          ": " +
          (i.client || "") +
          (i.notes && !String(i.notes).startsWith("AI:")
            ? " (" + i.notes + ")"
            : ""),
        in: +i.amount || 0,
        out: 0,
        fund: i.id,
      });
  });
  S.floats.forEach((f) => {
    if (f.account !== aid || f.type === "spend") return;
    const n = empN(f.employeeId);
    if (f.type === "give")
      L.push({
        date: f.date,
        t: tr("অগ্রিম দেওয়া") + ": " + n,
        in: 0,
        out: +f.amount || 0,
      });
    else if (f.type === "return")
      L.push({
        date: f.date,
        t: tr("অগ্রিম ফেরত") + ": " + n,
        in: +f.amount || 0,
        out: 0,
      });
    else if (f.type === "reimburse")
      L.push({
        date: f.date,
        t: tr("অগ্রিমের বাড়তি খরচ পরিশোধ") + ": " + n,
        in: 0,
        out: +f.amount || 0,
      });
  });
  S.expenses.forEach((e) => {
    if (e.account === aid && countable(e) && e.status === "paid")
      L.push({
        date: e.date,
        t: e.title,
        in: 0,
        out: +e.amount || 0,
        c: e.category,
      });
  });
  S.transfers.forEach((t) => {
    if (t.from === aid)
      L.push({
        date: t.date,
        t:
          tr("ট্রান্সফার →") +
          " " +
          accN(t.to) +
          (t.note ? " (" + t.note + ")" : ""),
        in: 0,
        out: +t.amount || 0,
        tr: t.id,
      });
    if (t.to === aid)
      L.push({
        date: t.date,
        t:
          tr("ট্রান্সফার ←") +
          " " +
          accN(t.from) +
          (t.note ? " (" + t.note + ")" : ""),
        in: +t.amount || 0,
        out: 0,
        tr: t.id,
      });
  });
  L.sort((a, b) => a.date.localeCompare(b.date));
  let r = Number(acc(aid)?.opening) || 0;
  L.forEach((x) => {
    r += x.in - x.out;
    x.bal = r;
  });
  return L.reverse();
}
V.accounts = () => {
  const bal = balances(),
    { from, to } = monthRange(monthNow());
  if (!acc(UI.ledAcc)) UI.ledAcc = S.cfg.accounts[0]?.id;
  const L = ledger(UI.ledAcc);
  return (
    ph(
      "ক্যাশ ও ব্যাংক",
      "Cash, Bank, bKash, Nagad — প্রতিটি অ্যাকাউন্টের লাইভ ব্যালেন্স",
      `<button class="btn pri" data-act="newFund">${I("plus")}টাকা জমা</button><button class="btn" data-act="newTransfer">${I("swap")}ট্রান্সফার</button>${ME.manager ? `<a class="btn" href="#config">অ্যাকাউন্ট যোগ/এডিট</a>` : ""}`,
    ) +
    `<div class="grid g4">${S.cfg.accounts
      .map((a) => {
        const m = ledger(a.id).filter((x) => inRange(x.date, from, to));
        return `<div class="card acc-card ${a.id === UI.ledAcc ? "on" : ""}" data-act="ledAcc" data-id="${a.id}" role="button" tabindex="0"><div class="t">${accIcon(a)}<span class="small muted">${accType(a.type)}</span></div><div class="muted small" style="margin-top:6px">${esc(a.name)}</div><div class="v num" style="color:${bal[a.id] < 0 ? "var(--red)" : "inherit"}">${fmt(bal[a.id])}</div><div class="small"><span class="down">+${fmtK(sum(m, "in"))}</span> <span class="up" style="margin-left:8px">−${fmtK(sum(m, "out"))}</span> <span class="muted">এই মাসে</span></div></div>`;
      })
      .join("")}</div>
  <div class="card mt"><div class="card-h"><h3>${esc(accN(UI.ledAcc))} — লেজার</h3><span>শুরুর ব্যালেন্স ${fmt(acc(UI.ledAcc)?.opening)}</span></div>
  ${
    L.length
      ? `<div class="tw" style="margin-top:10px"><table class="tbl cards"><thead><tr><th>তারিখ</th><th>বিবরণ</th><th class="right">জমা</th><th class="right">খরচ</th><th class="right">ব্যালেন্স</th></tr></thead><tbody>${L.slice(
          0,
          300,
        )
          .map(
            (x) =>
              `<tr><td class="c-hide num">${fds(x.date)}</td><td class="c-main"><b>${esc(x.t)}</b><small>${fds(x.date)}</small></td><td class="c-meta num" style="color:var(--green)">${x.in ? "+" + fmt(x.in) : ""}</td><td class="amt num" style="color:${x.out ? "var(--red)" : "var(--green)"}">${x.out ? "−" + fmt(x.out) : "+" + fmt(x.in)}</td><td class="c-meta right num">${fmt(x.bal)}${x.tr && ME.manager ? ` <button class="btn ic sm dng" data-act="delTransfer" data-id="${x.tr}" aria-label="ট্রান্সফার মুছুন">${I("trash")}</button>` : ""}${x.fund && ME.manager ? ` <button class="btn ic sm dng" data-act="delFund" data-id="${x.fund}" aria-label="জমা মুছুন">${I("trash")}</button>` : ""}</td></tr>`,
          )
          .join("")}</tbody></table></div>`
      : empty(
          "এই অ্যাকাউন্টে কোনো লেনদেন নেই",
          "খরচ বা আয় এন্ট্রিতে এই অ্যাকাউন্ট বেছে নিলে এখানে দেখা যাবে।",
        )
  }</div>`
  );
};

