/* ================= modal plumbing ================= */
let MCTX = null;
function modal({ title, body, foot, wide, drawer }) {
  const r = $("#modalRoot");
  r.innerHTML = tr(
    drawer
      ? `<div class="ov" data-ov style="padding:0"></div><div class="drawer" role="dialog" aria-modal="true"><div class="md-h"><h2>${title}</h2><button class="btn ic" data-act="closeModal" aria-label="বন্ধ">${I("x")}</button></div><div class="md-b">${body}</div>${foot ? `<div class="md-f" style="border-radius:0">${foot}</div>` : ""}</div>`
      : `<div class="ov" data-ov><div class="md ${wide ? "wide" : ""}" role="dialog" aria-modal="true"><div class="md-h"><h2>${title}</h2><button class="btn ic" data-act="closeModal" aria-label="বন্ধ">${I("x")}</button></div><div class="md-b">${body}</div>${foot ? `<div class="md-f">${foot}</div>` : ""}</div></div>`,
  );
  if (!drawer)
    setTimeout(() => {
      const f = r.querySelector(
        ".md-b input:not([type=hidden]):not([type=checkbox]):not([type=file]),.md-b select,.md-b textarea",
      );
      f && f.focus();
    }, 60);
}
function closeModal() {
  $("#modalRoot").innerHTML = "";
  MCTX = null;
}
const fv = (n) => {
  const el = $(`#modalRoot [name="${n}"]`);
  if (!el) return "";
  return el.type === "checkbox" ? el.checked : unmk(el.value).trim();
};
function need(names) {
  let ok = true;
  names.forEach((n) => {
    const el = $(`#modalRoot [name="${n}"]`);
    const fl = el && el.closest(".fl");
    const bad =
      !el ||
      !String(el.value).trim() ||
      (el.type === "number" && !(Number(el.value) > 0));
    if (fl) fl.classList.toggle("err", bad);
    if (bad) ok = false;
  });
  if (!ok) {
    const f = $("#modalRoot .fl.err .in");
    f && f.focus();
  }
  return ok;
}
const F = (label, name, input, { req, full, hint, em } = {}) =>
  `<div class="fl${full ? " full" : ""}"><label for="f_${name}">${label}${req ? ' <span class="rq">*</span>' : ""}</label>${input}${hint ? `<div class="hint">${hint}</div>` : ""}<div class="em">${em || "এই ঘরটি পূরণ করুন"}</div></div>`;
const inp = (name, val, attrs = "") =>
  `<input class="in" id="f_${name}" name="${name}" value="${esc(val ?? "")}" ${attrs}>`;
const sel = (name, opts, attrs = "") =>
  `<select class="in" id="f_${name}" name="${name}" ${attrs}>${opts}</select>`;
function confirmBox(title, text, yes, fn, danger = true) {
  modal({
    title,
    body: `<p style="margin:0">${text}</p>`,
    foot: `<button class="btn" data-act="closeModal">না, থাক</button><button class="btn ${danger ? "dng fill" : "pri"}" id="cfYes">${yes}</button>`,
  });
  $("#cfYes").onclick = async () => {
    $("#cfYes").disabled = true;
    try {
      await fn();
    } finally {
      closeModal();
    }
  };
}
function busy(btn, on, txt) {
  if (!btn) return;
  if (on) {
    btn.dataset.t = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = `<span class="spin" style="width:14px;height:14px;border-width:2px"></span>${txt || "সেভ হচ্ছে…"}`;
  } else {
    btn.disabled = false;
    if (btn.dataset.t) btn.innerHTML = btn.dataset.t;
  }
}
function vendorNames() {
  return [
    ...new Set([
      ...S.vendors.map((v) => v.name),
      ...S.expenses.map((e) => e.vendor).filter(Boolean),
    ]),
  ].sort();
}
async function ensureVendor(name) {
  name = (name || "").trim();
  if (!name || S.vendors.some((v) => norm(v.name) === norm(name))) return;
  try {
    await Store.save("vendors", { name }, { silent: true });
  } catch {}
}

