async function compress(file, max, q) {
  if (!file.type.startsWith("image/") || file.type === "image/gif") return file;
  const img = await new Promise((res, rej) => {
    const i = new Image();
    i.onload = () => res(i);
    i.onerror = rej;
    i.src = URL.createObjectURL(file);
  });
  const s = Math.min(1, max / Math.max(img.width, img.height)),
    c = document.createElement("canvas");
  c.width = Math.round(img.width * s);
  c.height = Math.round(img.height * s);
  c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
  return await new Promise((r) =>
    c.toBlob((b) => r(b || file), "image/jpeg", q),
  );
}
async function uploadReceipt(file) {
  const assets = await cap("assets");
  if (assets) {
    const b = await compress(file, 1600, 0.82);
    const r = await assets.upload(b);
    return {
      receiptId: r.id,
      receiptType: b.type || file.type,
      receiptData: "",
    };
  }
  if (!file.type.startsWith("image/"))
    throw new Error("এখানে শুধু ছবি রসিদ সেভ করা যায়");
  const b = await compress(file, 900, 0.6);
  const url = await new Promise((r) => {
    const fr = new FileReader();
    fr.onload = () => r(fr.result);
    fr.readAsDataURL(b);
  });
  if (url.length > 190000) throw new Error("ছবিটি অনেক বড়");
  return { receiptData: url, receiptId: "", receiptType: "image/jpeg" };
}
