async function deleteExpense(id) {
  const e = S.expenses.find((x) => x.id === id);
  if (!e) return;
  await Store.del("expenses", id).catch(() => {});
  if (e.payrollId) {
    const p = S.payroll.find((x) => x.id === e.payrollId);
    if (p && p.expenseId === id)
      Store.save("payroll", {
        ...p,
        paid: false,
        paidDate: "",
        expenseId: "",
      }).catch(() => {});
  }
  if (e.planId) {
    const p = S.plans.find((x) => x.id === e.planId);
    if (p && p.paidMonths) {
      const pm = { ...p.paidMonths };
      Object.keys(pm).forEach((k) => {
        if (pm[k] === id) delete pm[k];
      });
      Store.save("plans", { ...p, paidMonths: pm }).catch(() => {});
    }
  }
  if (e.dollarId) Store.del("dollars", e.dollarId).catch(() => {});
  return e;
}

