async function genPayroll() {
  const m = UI.payMonth;
  const miss = S.employees.filter(
    (e) =>
      e.active !== false &&
      !S.payroll.some((r) => r.month === m && r.employeeId === e.id),
  );
  await pool(miss, 4, (e) =>
    Store.save(
      "payroll",
      {
        month: m,
        employeeId: e.id,
        base: Number(e.salary) || 0,
        incentive: 0,
        bonus: 0,
        advance: 0,
        deduction: 0,
        paid: false,
      },
      { silent: true },
    ),
  );
  schedule();
  toast(`${miss.length} জনের পে-রোল শিট তৈরি হয়েছে`);
}
