async function saveDollar(d, src = "dollar") {
  d.id = newId();
  d.bdt = Math.round(d.usd * d.rate * 100) / 100;
  const ex = {
    date: d.date,
    title: `ডলার ক্রয় ${usd(d.usd)} @ ৳${d.rate}`,
    amount: d.bdt,
    category: pickCat("dollar"),
    team: d.team || "",
    account: d.account,
    status: "paid",
    vendor: d.vendor,
    notes: d.purpose,
    submittedBy: meEmp(),
    source: src,
    dollarId: d.id,
    approval: ME.manager || !S.cfg.approvalRequired ? "approved" : "pending",
    approvedAt: Date.now(),
  };
  const e = await Store.save("expenses", ex);
  d.expenseId = e.id;
  await Store.save("dollars", d);
  ensureVendor(d.vendor);
  return e;
}

/* ================= Vouchers ================= */
function nextVno() {
  const p = S.cfg.voucherPrefix || "V-";
  const num = (s) => parseInt(String(s || "").replace(/\D/g, ""), 10) || 0;
  let n = 0;
  for (const e of S.expenses) n = Math.max(n, num(e.vno));
  for (const v of S.vouchers) n = Math.max(n, num(v.no));
  return p + String(n + 1).padStart(5, "0");
}
const nextVoucherNo = nextVno;
function voucherForm(v, fromExp) {
  const isNew = !v;
  const r = v
    ? clone(v)
    : {
        no: nextVoucherNo(),
        date: today(),
        items: [{ desc: "", qty: 1, rate: 0 }],
        discount: 0,
        paid: 0,
        account: S.cfg.accounts[0]?.id,
      };
  if (fromExp) {
    Object.assign(r, {
      date: fromExp.date,
      vendor: fromExp.vendor || "",
      items: [{ desc: fromExp.title, qty: 1, rate: fromExp.amount }],
      paid: fromExp.status === "paid" ? fromExp.amount : 0,
      account: fromExp.account,
      expenseId: fromExp.id,
      notes: fromExp.notes || "",
    });
  }
  MCTX = { kind: "vou", rec: r };
  const itemRows = () =>
    r.items
      .map(
        (it, i) =>
          `<tr data-i="${i}"><td><input class="in" data-it="desc" value="${esc(it.desc)}" placeholder="বিবরণ"></td><td style="width:80px"><input class="in num" type="number" min="0" data-it="qty" value="${it.qty}"></td><td style="width:120px"><input class="in num" type="number" min="0" step="any" data-it="rate" value="${it.rate}"></td><td class="right num" style="width:110px"><b>${fmt((+it.qty || 0) * (+it.rate || 0))}</b></td><td style="width:40px"><button class="btn ic sm" data-act="vRm" data-i="${i}" aria-label="সারি মুছুন">${I("x")}</button></td></tr>`,
      )
      .join("");
  modal({
    wide: true,
    title: isNew ? "নতুন ক্যাশ মেমো / ভাউচার" : "মেমো এডিট",
    body: `<div class="fg" style="grid-template-columns:repeat(3,minmax(0,1fr))">${F("মেমো নং", "no", inp("no", r.no), { req: true })}${F("তারিখ", "date", inp("date", r.date, 'type="date"'), { req: true })}${F(
      "ভেন্ডর / প্রাপক",
      "vendor",
      inp("vendor", r.vendor, 'list="vendorList"') +
        `<datalist id="vendorList">${vendorNames()
          .map((x) => `<option value="${esc(x)}">`)
          .join("")}</datalist>`,
      { req: true },
    )}${F("প্রাপকের ফোন", "vphone", inp("vphone", r.vphone))}${F("পেমেন্ট মাধ্যম", "account", sel("account", accOpts(r.account) + opt("__float", "কর্মীর অগ্রিম থেকে (জমাদাতার হাতের টাকা)", r.account), "data-accsel"), { em: "কর্মীর অগ্রিম থেকে খরচ হলে “জমা দিয়েছেন” ঘরে কর্মী বেছে নিন" })}${F("পরিশোধিত (৳)", "paid", inp("paid", r.paid, 'type="number" min="0" step="any"'))}</div>
    <div class="tw mt"><table class="tbl vline"><thead><tr><th>বিবরণ</th><th>পরিমাণ</th><th>দর (৳)</th><th class="right">মোট</th><th></th></tr></thead><tbody id="vItems">${itemRows()}</tbody></table></div>
    <div class="row between wrap mt"><button class="btn sm" data-act="vAdd">${I("plus")}আইটেম যোগ</button><div class="row"><span class="muted">ছাড় (৳)</span><input class="in num" style="width:110px;height:34px" type="number" min="0" name="discount" value="${r.discount || 0}"><span class="muted" style="margin-left:10px">মোট</span><b class="num" id="vTot" style="font-size:18px">${fmt(vTotal(r))}</b></div></div>
    <div class="fg mt">${F("নোট", "notes", inp("notes", r.notes), { full: true })}${isNew && !fromExp ? `<label class="toggle"><input type="checkbox" name="asExp" checked><span>এই মেমোর টাকা খরচ হিসেবেও যোগ করুন</span></label>${F("খরচের ক্যাটাগরি", "vcat", sel("vcat", catOpts("misc")))}` : ""}</div>`,
    foot: `<button class="btn" data-act="closeModal">বাতিল</button><button class="btn" data-act="saveVoucher" data-pdf="1">${I("down")}সেভ ও PDF</button><button class="btn pri" data-act="saveVoucher">সেভ করুন</button>`,
  });
  MCTX.redraw = () => {
    $("#vItems").innerHTML = tr(itemRows());
    $("#vTot").textContent = fmt(vTotal(r));
  };
  $("#vItems").oninput = (ev) => {
    const tr = ev.target.closest("tr"),
      k = ev.target.dataset.it;
    if (!tr || !k) return;
    const it = r.items[+tr.dataset.i];
    it[k] = k === "desc" ? unmk(ev.target.value) : Number(ev.target.value) || 0;
    tr.querySelector("td:nth-child(4) b").textContent = fmt(
      (+it.qty || 0) * (+it.rate || 0),
    );
    r.discount = Number(fv("discount")) || 0;
    $("#vTot").textContent = fmt(vTotal(r));
  };
  $("#modalRoot [name=discount]").oninput = () => {
    r.discount = Number(fv("discount")) || 0;
    $("#vTot").textContent = fmt(vTotal(r));
  };
}
async function saveVoucher(btn, pdf) {
  if (!need(["no", "date", "vendor"])) return;
  const r = MCTX.rec;
  r.items = r.items.filter((i) => i.desc || i.rate);
  if (!r.items.length) return toast("অন্তত একটি আইটেম দিন", "err");
  Object.assign(r, {
    no: fv("no"),
    date: fv("date"),
    vendor: fv("vendor"),
    vphone: fv("vphone"),
    account: fv("account"),
    paid: Number(fv("paid")) || 0,
    discount: Number(fv("discount")) || 0,
    notes: fv("notes"),
  });
  const asExp = fv("asExp"),
    vcat = fv("vcat");
  busy(btn, true);
  try {
    if (asExp && !r.expenseId) {
      const e = await Store.save("expenses", {
        date: r.date,
        title: `${r.items[0].desc}${r.items.length > 1 ? ` + আরও ${r.items.length - 1}টি` : ""} (${r.no})`,
        amount: vTotal(r),
        category: pickCat(vcat),
        account: r.account,
        status: r.paid >= vTotal(r) ? "paid" : "pending",
        vendor: r.vendor,
        submittedBy: meEmp(),
        approval:
          ME.manager || !S.cfg.approvalRequired ? "approved" : "pending",
        approvedAt: Date.now(),
        source: "voucher",
        notes: r.notes,
      });
      r.expenseId = e.id;
    }
    const saved = await Store.save("vouchers", r);
    ensureVendor(r.vendor);
    closeModal();
    toast("মেমো সেভ হয়েছে");
    if (pdf) voucherPdf(saved);
  } catch {
    busy(btn, false);
  }
}

