async function payPlan(id) {
  const p = S.plans.find((x) => x.id === id);
  if (!p) return;
  const m = UI.planMonth,
    d = `${m}-${pad(Math.min(p.day || 1, daysIn(m)))}`;
  confirmBox(
    "পরিশোধ নিশ্চিত করুন",
    `<b>${esc(p.title)}</b> — ${fmt(p.amount)}<br><span class="muted">তারিখ ${fd(d)}, ${esc(accN(p.account))} থেকে। খরচ হিসেবে যোগ হবে।</span>`,
    "পরিশোধ করুন",
    async () => {
      const e = await Store.save("expenses", {
        date: d,
        title: p.title,
        amount: p.amount,
        category: pickCat(p.category),
        team: p.team || "",
        account: p.account,
        status: "paid",
        vendor: p.vendor || "",
        approval: "approved",
        approvedBy: S.cfg.defaultApprover,
        approvedAt: Date.now(),
        source: "plan",
        planId: p.id,
      });
      await Store.save("plans", {
        ...p,
        paidMonths: { ...(p.paidMonths || {}), [m]: e.id },
      });
      toast("পরিশোধ হয়েছে");
    },
    false,
  );
}

/* ================= Reminders ================= */
const dayDiff = (a, b) => Math.round((parseD(a) - parseD(b)) / 864e5);
const REM_KIND = {
  subscription: ["সাবস্ক্রিপশন", "software"],
  vendor: ["ভেন্ডর পেমেন্ট", "misc"],
  refund: ["রিফান্ড", "refund"],
  advance: ["অগ্রিম / অ্যাডভান্স", "misc"],
  bill: ["বিল", "utility"],
  rent: ["ভাড়া", "rent"],
  other: ["অন্যান্য", "misc"],
};
const REP = {
  none: "একবার",
  weekly: "প্রতি সপ্তাহে",
  monthly: "প্রতি মাসে",
  quarterly: "প্রতি ৩ মাসে",
  yearly: "প্রতি বছরে",
};
const remBDT = (r) =>
  r.currency === "USD"
    ? (Number(r.amount) || 0) * (Number(r.rate) || S.cfg.usdRate)
    : Number(r.amount) || 0;
const remAmt = (r) => (r.currency === "USD" ? usd(r.amount) : fmt(r.amount));
function remState(r) {
  const days = (
    r.remind && r.remind.length ? r.remind : S.cfg.reminderDays || [7, 3, 1]
  )
    .map(Number)
    .filter((n) => n >= 0);
  const dl = dayDiff(r.due, today()),
    mx = Math.max(0, ...days);
  return {
    dl,
    overdue: dl < 0,
    alert: dl <= mx,
    hit: days.includes(dl) || dl <= 0,
    days,
  };
}
const dismissed = () => {
  try {
    return JSON.parse(localStorage.getItem("moas-rem-dis") || "{}");
  } catch {
    return {};
  }
};
function reminderAlerts() {
  const dis = dismissed(),
    t = today();
  return S.reminders
    .filter((r) => r.active !== false && r.due)
    .map((r) => ({ ...r, ...remState(r) }))
    .filter((r) => r.alert && dis[r.id + "|" + r.due] !== t)
    .sort((a, b) => a.dl - b.dl);
}
function advanceDue(d, rep, anchor) {
  if (rep === "weekly") return addDays(d, 7);
  const n = { monthly: 1, quarterly: 3, yearly: 12 }[rep];
  if (!n) return d;
  const m = addMonths(d.slice(0, 7), n);
  return `${m}-${pad(Math.min(anchor || Number(d.slice(8)), daysIn(m)))}`;
}
const dueLabel = (dl) =>
  dl < 0
    ? `${-dl} দিন পার হয়েছে`
    : dl === 0
      ? "আজ পরিশোধের দিন"
      : dl === 1
        ? "আগামীকাল"
        : `${dl} দিন বাকি`;
function dueBadge(r) {
  const s = r.dl != null && r.days ? r : { ...r, ...remState(r) };
  const c =
    s.dl < 0
      ? "late"
      : s.dl === 0
        ? "today"
        : s.dl <= Math.max(0, ...s.days)
          ? "soon"
          : "ok";
  const d = parseD(r.due);
  return `<div class="due ${c}"><b>${pad(d.getDate())}</b><small>${MN[d.getMonth()]}</small></div>`;
}
function remRowMini(r) {
  return `<div class="list-row">${dueBadge(r)}<div style="flex:1;min-width:0"><b style="font-weight:600">${esc(r.title)}</b><div class="small ${r.dl < 0 ? "up" : "muted"}">${dueLabel(r.dl)}</div></div><b class="num">${remAmt(r)}</b>${ME.manager ? `<button class="btn sm pri" data-act="payRem" data-id="${r.id}">পরিশোধ</button>` : ""}</div>`;
}
V.reminders = () => {
  const f = UI.remKind || "",
    all = S.reminders
      .filter((r) => r.due)
      .map((r) => ({ ...r, ...remState(r) }));
  const act = all
      .filter((r) => r.active !== false && (!f || r.kind === f))
      .sort((a, b) => a.dl - b.dl),
    done = all
      .filter((r) => r.active === false && (!f || r.kind === f))
      .sort((a, b) => b.due.localeCompare(a.due))
      .slice(0, 15);
  const od = act.filter((r) => r.overdue),
    wk = act.filter((r) => r.dl >= 0 && r.dl <= 7),
    mo = act.filter((r) => r.due.slice(0, 7) === monthNow());
  const subM = sum(
    act.filter((r) => r.kind === "subscription"),
    (r) =>
      remBDT(r) *
      ({ weekly: 4.33, monthly: 1, quarterly: 1 / 3, yearly: 1 / 12 }[
        r.repeat
      ] || 0),
  );
  const row = (
    r,
  ) => `<div class="list-row" style="align-items:flex-start">${dueBadge(r)}<div style="flex:1;min-width:0"><b style="font-weight:600">${esc(r.title)}</b> <span class="chip" style="margin-left:4px">${REM_KIND[r.kind]?.[0] || "অন্যান্য"}</span>
    <div class="small muted" style="margin-top:2px">${fd(r.due)} — <span class="${r.dl < 0 ? "up" : r.dl <= 3 ? "" : ""}" style="font-weight:600">${r.active === false ? "সম্পন্ন" : dueLabel(r.dl)}</span> — ${REP[r.repeat] || "একবার"}${r.vendor ? ", " + esc(r.vendor) : ""}</div>
    ${r.active !== false ? `<div style="margin-top:5px"><span class="small muted">মনে করাবে: </span>${r.days.map((d) => `<span class="rd ${d === r.dl ? "hit" : ""}">${d === 0 ? "ওই দিন" : d + " দিন আগে"}</span>`).join("")}</div>` : ""}</div>
    <div class="right" style="flex:none"><b class="num">${remAmt(r)}</b>${r.currency === "USD" ? `<div class="small muted num">≈ ${fmt(remBDT(r))}</div>` : ""}<div class="row" style="justify-content:flex-end;margin-top:6px;gap:4px">${ME.manager && r.active !== false ? `<button class="btn sm pri" data-act="payRem" data-id="${r.id}">পরিশোধ</button>` : ""}${ME.manager ? `<button class="btn ic sm" data-act="editRem" data-id="${r.id}" aria-label="এডিট">${I("edit")}</button>` : ""}</div></div></div>`;
  return (
    ph(
      "রিমাইন্ডার ও সাবস্ক্রিপশন",
      "সাবস্ক্রিপশন, ভেন্ডর পেমেন্ট, রিফান্ড, অগ্রিম — নিজের ঠিক করা দিনে মনে করিয়ে দেবে",
      ME.manager
        ? `<button class="btn pri" data-act="newRem">${I("plus")}নতুন রিমাইন্ডার</button>`
        : "",
    ) +
    `<div class="grid g4"><div class="card kpi hero"><div class="l">${I("alert")}সময় পার হয়েছে</div><div class="v num">${od.length}</div><div class="s">${fmt(sum(od, remBDT))}</div></div>
   <div class="card kpi"><div class="l">${I("clock")}আগামী ৭ দিনে</div><div class="v num">${fmt(sum(wk, remBDT))}</div><div class="s">${wk.length}টি পেমেন্ট</div></div>
   <div class="card kpi"><div class="l">${I("cal")}এই মাসে মোট</div><div class="v num">${fmt(sum(mo, remBDT))}</div><div class="s">${mo.length}টি পেমেন্ট</div></div>
   <div class="card kpi"><div class="l">${I("repeat")}সাবস্ক্রিপশনের মাসিক খরচ</div><div class="v num">${fmt(subM)}</div><div class="s">${act.filter((r) => r.kind === "subscription").length}টি সক্রিয়</div></div></div>
  <div class="card mt"><div class="card-b row wrap" style="gap:10px"><div class="seg"><button class="${!f ? "on" : ""}" data-act="remKind" data-v="">সব</button>${Object.entries(
    REM_KIND,
  )
    .map(
      ([k, v]) =>
        `<button class="${f === k ? "on" : ""}" data-act="remKind" data-v="${k}">${v[0]}</button>`,
    )
    .join("")}</div></div>
  <div class="card-b" style="padding-top:0">${act.length ? act.map(row).join("") : empty("কোনো সক্রিয় রিমাইন্ডার নেই", "Canva, Adobe, hosting, ভেন্ডরের বাকি বা রিফান্ডের তারিখ যোগ করুন — নির্দিষ্ট দিনে মনে করিয়ে দেবে।", ME.manager ? `<button class="btn pri" data-act="newRem">${I("plus")}নতুন রিমাইন্ডার</button>` : "")}</div></div>
  ${done.length ? `<div class="card mt"><div class="card-h"><h3>সম্পন্ন / বন্ধ</h3></div><div class="card-b" style="padding-top:6px">${done.map(row).join("")}</div></div>` : ""}
  <p class="small muted" style="margin-top:14px">${I("bell")} রিমাইন্ডার এই সফটওয়্যার খোলা থাকলে উপরের ঘণ্টা আইকনে ও ড্যাশবোর্ডে দেখা যায়।</p>`
  );
};
const DAY_CHOICES = [30, 15, 10, 7, 5, 3, 2, 1, 0];
