async function saveRem(btn) {
  if (!need(["title", "amount", "due"])) return;
  const r = MCTX.rec;
  const custom = fv("customDays")
    .split(/[,\s]+/)
    .map(Number)
    .filter((n) => Number.isFinite(n) && n >= 0 && n <= 365);
  const days = [...new Set([...MCTX.days, ...custom])].sort((a, b) => b - a);
  Object.assign(r, {
    title: fv("title"),
    kind: fv("kind"),
    category: fv("category"),
    amount: Number(fv("amount")),
    currency: fv("currency"),
    rate: Number(fv("rate")) || S.cfg.usdRate,
    due: fv("due"),
    repeat: fv("repeat"),
    remind: days.length ? days : [0],
    vendor: fv("vendor"),
    account: fv("account"),
    notes: fv("notes"),
    active: fv("active"),
    anchor: Number(fv("due").slice(8)),
  });
  busy(btn, true);
  try {
    await Store.save("reminders", r);
    closeModal();
    toast("রিমাইন্ডার সেভ হয়েছে");
  } catch {
    busy(btn, false);
  }
}
function payRem(id) {
  const r = S.reminders.find((x) => x.id === id);
  if (!r) return;
  const isU = r.currency === "USD";
  modal({
    title: "রিমাইন্ডার পরিশোধ",
    body: `<p style="margin-top:0"><b>${esc(r.title)}</b> — ${remAmt(r)} <span class="muted">(${fd(r.due)})</span></p><div class="fg">
    ${isU ? F("ডলার ($)", "pusd", inp("pusd", r.amount, 'type="number" step="any" data-pc')) + F("রেট (৳)", "prate", inp("prate", r.rate || S.cfg.usdRate, 'type="number" step="any" data-pc')) : ""}
    ${F("টাকা (৳)", "pamt", inp("pamt", Math.round(remBDT(r) * 100) / 100, 'type="number" step="any"'), { req: true })}
    ${F("পরিশোধের তারিখ", "pdate", inp("pdate", today(), 'type="date"'))}${F("কোন অ্যাকাউন্ট থেকে", "pacc", sel("pacc", accOpts(r.account)))}</div>
    <p class="small muted">${esc(cat(r.category).name)} ক্যাটাগরিতে খরচ হিসেবে যোগ হবে, ভাউচার নম্বরসহ।${r.repeat && r.repeat !== "none" ? ` পরবর্তী তারিখ হবে <b>${fd(advanceDue(r.due, r.repeat, r.anchor))}</b>।` : " এরপর রিমাইন্ডারটি সম্পন্ন হিসেবে বন্ধ হবে।"}</p>`,
    foot: `<button class="btn" data-act="closeModal">বাতিল</button><button class="btn pri" id="prGo">পরিশোধ নিশ্চিত করুন</button>`,
  });
  $$("#modalRoot [data-pc]").forEach(
    (el) =>
      (el.oninput = () => {
        $("#f_pamt").value =
          Math.round(
            (Number(fv("pusd")) || 0) * (Number(fv("prate")) || 0) * 100,
          ) / 100;
      }),
  );
  $("#prGo").onclick = async (ev) => {
    if (!need(["pamt"])) return;
    const b = ev.currentTarget;
    busy(b, true);
    try {
      const ex = await Store.save("expenses", {
        date: fv("pdate"),
        title: r.title + (isU ? ` (${usd(fv("pusd"))})` : ""),
        amount: Number(fv("pamt")),
        category: pickCat(r.category),
        account: fv("pacc"),
        status: "paid",
        vendor: r.vendor || "",
        submittedBy: meEmp(),
        approval: "approved",
        approvedBy: S.cfg.defaultApprover,
        approvedAt: Date.now(),
        source: "reminder",
        reminderId: r.id,
        notes: r.notes || "",
      });
      const log = [
        ...(r.paidLog || []),
        { due: r.due, date: fv("pdate"), expenseId: ex.id, amount: ex.amount },
      ].slice(-24);
      await Store.save("reminders", {
        ...r,
        paidLog: log,
        ...(r.repeat && r.repeat !== "none"
          ? { due: advanceDue(r.due, r.repeat, r.anchor) }
          : { active: false }),
      });
      closeModal();
      toast(`পরিশোধ হয়েছে (${esc(ex.vno)})`, "", {
        label: "ভাউচার PDF",
        fn: () => expenseMemoPdf(ex),
      });
    } catch {
      busy(b, false);
    }
  };
}
