  const re =
    /(\$\s*)?(\d+(?:[.,]\d+)*)\s*(\$|dollar|ডলার|usd|taka|টাকা|tk|৳)?/g;
  let m;
  while ((m = re.exec(t))) {
    const after = t.slice(m.index + m[0].length, m.index + m[0].length + 9);
    if (
      /^\s*(tarikh|তারিখ|th\b|st\b|nd\b|rd\b|din|দিন|days?\b|date)/.test(
        after,
      ) ||
      /^\s*(,|ar|আর|and|o|ও)\s*\d+\s*(din|দিন)/.test(after)
    )
      continue;
    if (
      /\d{4}-\d{2}-\d{2}/.test(t.slice(Math.max(0, m.index - 5), m.index + 10))
    )
      continue;
    all.push({ n: parseFloat(m[2].replace(/,/g, "")), u: m[1] || m[3] || "" });
  }
  const pick = all.find((x) => x.u) || all.sort((a, b) => b.n - a.n)[0];
  const currency = pick && /\$|dollar|ডলার|usd/.test(pick.u) ? "USD" : "BDT";
  const brand = raw.match(/[A-Z][A-Za-z0-9+.]*(?:\s[A-Z][A-Za-z0-9+.]*)?/);
  let title = brand
    ? brand[0]
    : raw
        .replace(/[0-9০-৯$৳][0-9০-৯.,]*/g, "")
        .replace(
          /(taka|টাকা|tk|protimash|প্রতি মাসে|তারিখে|tarikh e|din age|দিন আগে|mone koraio|মনে করাবে|মনে করিয়ে দিও|remind|ar|আর)/gi,
          "",
        )
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 40);
