function lastMine() {
  const mine = S.expenses.filter((e) => !ME.uid || e.createdBy === ME.uid);
  const ids = UI.lastAdded || [];
  for (let i = ids.length - 1; i >= 0; i--) {
    const e = S.expenses.find((x) => x.id === ids[i]);
    if (e) return e;
  }
  return mine.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
}
