function xls(sheets, filename) {
  if (!window.XLSX) {
    toast("Excel লাইব্রেরি লোড হয়নি", "err");
    return;
  }
  const wb = XLSX.utils.book_new();
  sheets.forEach(([n, rows]) => {
    const ws = XLSX.utils.json_to_sheet(
      rows.length ? rows : [{ তথ্য: "ডেটা নেই" }],
    );
    ws["!cols"] = Object.keys(rows[0] || { a: 1 }).map((k) => ({
      wch: Math.min(
        40,
        Math.max(
          10,
          k.length + 4,
          ...rows.slice(0, 200).map((r) => String(r[k] ?? "").length + 2),
        ),
      ),
    }));
    XLSX.utils.book_append_sheet(wb, ws, n.slice(0, 31));
  });
  saveFile(
    filename,
    new Blob([XLSX.write(wb, { bookType: "xlsx", type: "array" })]),
  );
}
