function collectRows(listId) {
  return $$(`#${listId} [data-row]`).map((r) => {
    const o = { _id: r.dataset.row };
    $$("[data-k]", r).forEach((i) => (o[i.dataset.k] = unmk(i.value).trim()));
    return o;
  });
}
const slug = (s) =>
  (norm(s)
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 20) || "x") +
  "-" +
  Math.random().toString(36).slice(2, 6);
async function saveCats() {
  const rows = collectRows("catList").filter((r) => r.name);
  const old = S.cfg.categories;
  const cats = rows.map((r) => ({
    id: r._id.startsWith("new-") ? slug(r.name) : r._id,
    name: r.name,
    desc: r.desc,
    color: r.color || "#9AA4B6",
  }));
  if (!cats.some((c) => c.id === "misc"))
    cats.push(
      old.find((c) => c.id === "misc") ||
        DEF.categories.find((c) => c.id === "misc"),
    );
  const removed = old
    .filter((o) => !cats.some((c) => c.id === o.id))
    .map((o) => o.id);
  const affected = S.expenses.filter((e) => removed.includes(e.category));
  await Store.saveCfg({ ...S.cfg, categories: cats });
  if (affected.length) {
    await pool(affected, 4, (e) =>
      Store.save("expenses", { ...e, category: "misc" }, { silent: true }),
    );
    schedule();
  }
  toast(
    "ক্যাটাগরি সেভ হয়েছে" +
      (affected.length
        ? ` — ${affected.length}টি এন্ট্রি Miscellaneous-এ সরানো হয়েছে`
        : ""),
  );
}
