/* ================= events & init ================= */
document.addEventListener("click", (ev) => {
  const b = ev.target.closest("[data-act]");
  if (ev.target.matches("[data-ov]")) {
    closeModal();
    return;
  }
  if (!ev.target.closest("#ai")) closeAi();
  if (!ev.target.closest("#bellPanel") && !ev.target.closest("#bellBtn"))
    $("#bellPanel").classList.remove("open");
  if (b && ACT[b.dataset.act]) {
    if (b.tagName !== "INPUT") ev.preventDefault();
    ACT[b.dataset.act](b.dataset, b, ev);
  }
});
let fT;
function setF(path, val) {
  const p = path.split(".");
  if (p.length === 2) {
    UI[p[0]][p[1]] = val;
    if (p[1] === "preset" && val === "custom") {
      const r = monthRange(monthNow());
      const o = UI[p[0]];
      if (!o.from) o.from = r.from;
      if (!o.to) o.to = today();
    }
  } else UI[path] = val;
  UI.sel.clear();
}
document.addEventListener("input", (ev) => {
  const k = ev.target.dataset && ev.target.dataset.f;
  if (
    !k ||
    ev.target.tagName === "SELECT" ||
    ev.target.type === "date" ||
    ev.target.type === "month"
  )
    return;
  setF(k, ev.target.value);
  clearTimeout(fT);
  fT = setTimeout(render, 220);
});
document.addEventListener("change", (ev) => {
  const t = ev.target;
  if (t.id === "meSel") {
    try {
      localStorage.setItem("moas-me-emp", t.value);
    } catch {}
    toast("এই ডিভাইসের জন্য সেভ হয়েছে");
    return;
  }
  const k = t.dataset && t.dataset.f;
  if (!k || (t.tagName !== "SELECT" && t.type !== "date" && t.type !== "month"))
    return;
  if (!t.value && t.type === "month") return;
  setF(k, t.value);
  render();
});
document.addEventListener("keydown", (ev) => {
  if (ev.key === "Escape") {
    if ($("#modalRoot").innerHTML) closeModal();
    else closeAi();
  }
  if (!AUTHED) return;
  if (
    ev.key === "/" &&
    !/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)
  ) {
    ev.preventDefault();
    $("#aiIn").focus();
  }
  if (
    ev.key === "Enter" &&
    document.activeElement.getAttribute("role") === "button"
  )
    document.activeElement.click();
  if (
    ev.key === "Enter" &&
    document.activeElement.closest &&
    document.activeElement.closest(".md") &&
    document.activeElement.tagName === "INPUT" &&
    document.activeElement.type !== "checkbox"
  ) {
    const p = $("#modalRoot .md-f .btn.pri:last-child");
    if (p && !$("#vItems")) {
      ev.preventDefault();
      p.click();
    }
  }
});
