async function logout() {
  try {
    await fetch("/api/auth/logout", {
      method: "POST",
      credentials: "same-origin"
    });
  } catch (error) {
    console.warn("Logout request failed", error);
  }

  AUTHED = false;

  try {
    localStorage.removeItem("moas-auth");
    sessionStorage.removeItem("moas-auth");
  } catch {}

  closeModal();
  closeAi();

  const panel = $("#bellPanel");
  if (panel) panel.classList.remove("open");

  render();
}

let gateFails = 0,
  gateLockUntil = 0;
function gateShow() {
  const g = $("#gate");
  if (!g.classList.contains("on")) {
    g.classList.add("on");
    ["gateSub", "gRemT"].forEach((id) => {
      const e = $("#" + id);
      if (!e.dataset.o) e.dataset.o = e.textContent;
      e.textContent = tr(e.dataset.o);
    });
    $$("#gate label[for]").forEach((l) => {
      if (!l.dataset.o) l.dataset.o = l.textContent;
      l.textContent = tr(l.dataset.o);
    });
    $("#gGo").textContent = tr("লগইন");
    setTimeout(() => {
      const e = $("#gEmail");
      if (e && !e.value) e.focus();
      else $("#gPass").focus();
    }, 60);
  }
}

async function gateTry() {
  const err = $("#gErr");
  const btn = $("#gGo");

  if (Date.now() < gateLockUntil) {
    err.textContent = "Too many attempts. Try again later.";
    return;
  }

  const email = $("#gEmail").value.trim().toLowerCase();
  const password = $("#gPass").value;

  if (!email || !password) {
    err.textContent = "Enter email and password.";
    return;
  }

  btn.disabled = true;
  btn.textContent = "Logging in...";
  err.textContent = "";

  try {
    // MOAS LOGIN DIAGNOSTIC V1

    const response = await fetch("/api/auth/login", {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ email, password })
    });


    if (!response.ok) {
      gateFails++;

      if (gateFails >= 5) {
        gateLockUntil = Date.now() + 30000;
        gateFails = 0;
      }

      err.textContent =
        response.status === 401
          ? "Invalid email or password."
          : "Login failed. Please try again.";
      return;
    }

    gateFails = 0;
    AUTHED = true;
    await Store.init();

    $("#gPass").value = "";
    $("#gate").classList.remove("on");

    render();
    setTimeout(remDailyNotice, 1500);

  } catch (error) {
    console.error("Login failed:", error);
    err.textContent = "Cannot connect to backend server.";
  } finally {
    btn.disabled = false;
    btn.textContent = "Login";
  }
}


